from lib import *
S = SS('t25')
steps = [
    step("etcd 里“写完立刻读”:对 leader 写 key 并等到确认,马上到一个 follower 上读,各 300 次。网络没有额外延迟时:可串行化读(只读这个 follower 自己的状态)读到旧值 101 / 300 次,延迟中位数 0.35 ms;线性一致读(要向 leader 确认)读到旧值 0 / 300 次,延迟中位数 0.91 ms、p99 7.0 ms。peer 通信每个方向加 20 ms 时:可串行化读 300 / 300 次都是旧值(0.57 ms),线性一致读仍然 0 / 300 次旧值,但延迟中位数涨到 93.45 ms、p99 102.2 ms。线性一致读保证读到的不比任何已完成的写入旧,代价是多一次与 leader 的往返;可串行化读快,但可能读到旧值。", t=tl(S(1)), mark=lidx(S(1), 'peer 通信每个方向 +20 ms'), done=lidx(S(1), '网络无额外延迟'), b=bars([['无延迟:可串行化读读到旧值', 101, '101 / 300'], ['+20 ms:可串行化读读到旧值', 300, '300 / 300'], ['+20 ms:线性一致读读到旧值', 0, '0 / 300'], ['+20 ms:线性一致读延迟 ms', 93.45, '93.45']], 300, mark=[0, 1], done=[2], cur=[3]), kv=KV([['可串行化读', '快(0.35 ~ 0.57 ms),可能读到旧值'], ['线性一致读', '0 次旧值,延迟 0.91 → 93.45 ms'], ['代价', '多一次与 leader 的往返']], ['代价'])),
    step("Redis 主从(异步复制):写 master、立刻读 replica,各 300 次。无额外延迟时,读到旧值 73 / 300 次;master 与 replica 之间每个方向 +5 ms 或 +20 ms 时都是 300 / 300 次旧值——master 回复写入时 replica 还没收到。写完之后用 WAIT 1 0 等 1 个 replica 确认再读:三种条件下都是 0 / 300 次旧值,写 + WAIT + 读的总耗时中位数分别是 0.22 ms、12.94 ms、48.24 ms(异步时是 0.14 到 0.21 ms)。WAIT 用延迟换到了读 replica 不旧,但只保证这一个 replica,其它读者和其它 replica 不在保证里,它不是线性一致。", t=tl(S(2)), mark=lidx(S(2), '无额外延迟', '每个方向 +20 ms'), done=lidx(S(2), 'master ↔ replica 每个方向 +5 ms'), b=bars([['异步,无延迟:读到旧值', 73, '73 / 300'], ['异步,+5 ms:读到旧值', 300, '300 / 300'], ['WAIT,三种条件:读到旧值', 0, '0 / 300'], ['WAIT,+20 ms:总耗时 ms', 48.24, '48.24']], 300, mark=[0, 1], done=[2], cur=[3]), kv=KV([['异步复制', '写后读 replica 常常是旧的'], ['WAIT 1 0', '0 次旧值,代价是一个往返'], ['保证范围', '只保证等到的那个 replica']], ['保证范围'])),
    step("最终一致的收敛时间:写 master 之后轮询 replica 直到看到新值,各 200 次。无额外延迟:中位数 0.21 ms、p99 0.38 ms、最大 0.48 ms;每个方向 +5 ms:中位数 6.38 ms、p99 6.50 ms、最大 6.60 ms;每个方向 +20 ms:中位数 24.29 ms、p99 25.25 ms、最大 25.42 ms。“最终”有多久取决于复制延迟,链路越慢越久;没有人给它保证一个上限,链路断了就一直不收敛。", t=tl(S(3)), mark=lidx(S(3), '每个方向 +20 ms'), done=lidx(S(3), '无额外延迟', '每个方向 +5 ms'), b=bars([['无延迟 收敛中位数 ms', 0.21, '0.21'], ['+5 ms 收敛中位数 ms', 6.38, '6.38'], ['+20 ms 收敛中位数 ms', 24.29, '24.29']], 25, cur=[0, 1, 2]), kv=KV([['收敛时间', '≈ 复制链路的延迟'], ['无延迟', '亚毫秒'], ['上限', '没有保证']], ['上限'])),
    step("用线性一致性检查器判定:4 个客户端各做 3 次操作(读或写同一个 key),记录每个操作的开始和结束时间,检查有没有一个总顺序既满足“已结束的操作排在后开始的操作前面”、又满足寄存器语义,etcd 上 100 段历史,读走 follower。网络无额外延迟:可串行化读有 46 / 100 段不可线性化,线性一致读 0 / 100;peer 通信每个方向 +20 ms:可串行化读 100 / 100 段不可线性化,线性一致读 0 / 100。一段不可线性化的历史里,每段开头先写 init 再写 v0(都在其它操作开始前确认),之后却有读返回 init——比已经确认的 v0 还旧,任何总顺序都解释不了。线性一致不是一个口头概念,可以用检查器判定。", t=tl(S(4)), mark=lidx(S(4), '读到 init', '读 init'), done=lidx(S(4), '线性一致读', '100  | 100'), b=bars([['无延迟:可串行化读 不可线性化的段数', 46, '46 / 100'], ['+20 ms:可串行化读 不可线性化的段数', 100, '100 / 100'], ['线性一致读(两种条件)不可线性化的段数', 0, '0 / 100']], 100, mark=[0, 1], done=[2]), kv=KV([['可串行化读', '46 → 100 段不可线性化'], ['线性一致读', '两种条件下都是 0 段'], ['检查器', '找不到合法总顺序 = 不可线性化']], ['检查器'])),
]
A = mkartt('t25', 25, '分布式事务,线性一致,最终一致,etcd,Redis,线性一致性检查器,真实验证,动画演示',
    '实测线性一致与最终一致:etcd 写后立刻读 follower,可串行化读旧值 101 / 300(加 20 ms 延迟后 300 / 300),线性一致读 0 次旧值但延迟从 0.91 ms 到 93.45 ms;Redis 异步复制写后读 replica 旧值 73 / 300,WAIT 1 0 后 0 次;手写线性一致性检查器判定:可串行化读 46 到 100 / 100 段历史不可线性化,线性一致读 0。',
    '线性一致和最终一致到底差在哪?读 follower 会读到多旧的数据?把读请求变成线性一致要付出多少延迟?最终一致“最终”要多久?这篇用真实的 3 节点 etcd 和 Redis 主从,加上一个手写的线性一致性检查器,把它们的差别量出来。',
    [('101 / 300 → 0 / 300', '无额外延迟时,etcd follower 上可串行化读读到旧值的次数 → 线性一致读读到旧值的次数'), ('0.91 → 93.45 ms', '加 20 ms 的 peer 延迟后,线性一致读的延迟中位数(从 0.91 ms 涨上来)'), ('46 → 100 / 100', '检查器判定为不可线性化的历史段数:可串行化读,无延迟 → 加 20 ms 延迟')],
    [('读 follower', '<p>可串行化读只看 follower 自己的状态,快但可能比刚确认的写入旧;线性一致读要向 leader 确认,保证不旧,延迟随 leader 的往返上升。</p>'),
     ('异步复制', '<p>Redis master 回复写入时 replica 常常还没收到,写后读 replica 常是旧值;WAIT 1 0 能让这个 replica 不旧,但不是线性一致。</p>'),
     ('收敛时间', '<p>最终一致的“最终”约等于复制链路的延迟,没有上限保证。</p>'),
     ('线性一致性检查器', '<p>记录每个操作的开始和结束时间,找不到合法总顺序的历史就不是线性一致的;线性一致读 0 段违反,可串行化读大量违反。</p>')],
    steps,
    [ENV_T + '。本篇用真实的 3 节点 etcd 3.7.2(HTTP/JSON 网关长连接读写;peer 通信经过我加的延迟代理,延迟是对每个方向各加)、一主一从的 Redis 8.10.2(异步复制,replica 到 master 的连接也经过同样的代理)和我自己写的线性一致性检查器(单个寄存器、初值 None,深度优先 + 记忆化,历史只有 13 个操作左右);Redis 实验先预热复制链路并等偏移量对齐;每段 etcd 历史由 4 个线程各做 3 次操作,写走 leader、读走两个 follower',
     '没有验证:多个 key / 事务下的线性一致性(检查器只处理单个寄存器);etcd 的 ReadIndex 与租约读的差别(这里只比较了默认读和 serializable);Redis Sentinel / Cluster 下的故障转移与丢写;WAIT 的 timeout 非 0 的行为;因果一致(下一篇);我调试过程中发现我自己的延迟代理曾因给连接设了 2 秒超时而悄悄断开空闲连接,已修正,最终数字是修正后的结果'],
    '线性一致与最终一致')
